#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/git-tag.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Tag HEAD with a signed tag, and push only the tag with --push"
# MISE tools={uv="latest", python="3.14"}
# USAGE arg "<name>" help="the name of the tag"
# USAGE flag "--message <text>" help="the message of the tag; the default is the name"
# USAGE flag "--push" help="also push the tag to origin"

# The task tags HEAD with an annotated, signed tag (`git tag --sign`). It
# stops, and changes nothing, when the tree has uncommitted or untracked
# files, when the tag exists here or on origin, and with --push when origin
# does not contain HEAD: a CI run on a commit that no branch of origin has
# fails its check of the history. It does not examine the branch: a release
# task does that before it calls this task. With --push, it pushes only the
# tag, never a branch.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def git(*args):
  """Run git. Returns (code, stdout without the last line break)."""
  result = subprocess.run(["git", *args], check=False, stdout=subprocess.PIPE, text=True)
  return result.returncode, result.stdout.rstrip("\n")


def main():
  os.chdir(os.environ["MISE_PROJECT_ROOT"])
  name = os.environ.get("usage_name", "")
  message = os.environ.get("usage_message", "") or name
  push = os.environ.get("usage_push") == "true"

  helpers.print_header(f"Tagging {name} ...")
  if git("check-ref-format", f"refs/tags/{name}")[0] != 0:
    helpers.print_error(f"'{name}' is not a valid tag name.")
    return 1
  if git("status", "--porcelain")[1]:
    helpers.print_error("The tree has uncommitted or untracked files. Commit or remove them first.")
    return 1
  if git("rev-parse", "--quiet", "--verify", f"refs/tags/{name}")[0] == 0:
    helpers.print_error(f"The tag {name} already exists here.")
    return 1
  has_origin = git("remote", "get-url", "origin")[0] == 0
  if has_origin:
    code, out = git("ls-remote", "--tags", "origin", f"refs/tags/{name}")
    if code != 0:
      helpers.print_error("Cannot read the tags of origin.")
      return 1
    if out:
      helpers.print_error(f"The tag {name} already exists on origin.")
      return 1
  if push:
    if not has_origin:
      helpers.print_error("--push needs an origin remote.")
      return 1
    if git("fetch", "--quiet", "origin")[0] != 0:
      helpers.print_error("Cannot fetch origin.")
      return 1
    if not git("branch", "--remotes", "--contains", "HEAD")[1]:
      helpers.print_error("No branch of origin contains HEAD. Push or land the commit first.")
      return 1

  helpers.print_wait(f"Creating the signed tag {name} ... ")
  if git("tag", "--sign", name, "-m", message)[0] != 0:
    helpers.print_error()
    helpers.print_error(f"FAILED to create the tag {name}. Examine the signing config of git.")
    return 1
  helpers.print_success()
  if push:
    helpers.print_wait(f"Pushing the tag {name} to origin ... ")
    if git("push", "--quiet", "origin", f"refs/tags/{name}")[0] != 0:
      helpers.print_error()
      helpers.print_error(f"FAILED to push the tag {name}. It stays here: git push origin {name}")
      return 1
    helpers.print_success()
  return 0


if __name__ == "__main__":
  sys.exit(main())
